### 7. Performance Best Practices

#### Image Optimization

```vue
<!-- Using @nuxt/image -->
<template>
  <!-- Responsive images -->
  <NuxtImg
    src="/images/product.jpg"
    alt="Product image"
    width="400"
    height="300"
    format="webp"
    loading="lazy"
    sizes="sm:100vw md:50vw lg:400px"
  />
  
  <!-- Priority loading for LCP images -->
  <NuxtImg
    src="/images/hero.jpg"
    alt="Hero image"
    width="1200"
    height="600"
    priority
  />
</template>
```

```typescript
// nuxt.config.ts - Image module configuration
export default defineNuxtConfig({
  image: {
    quality: 80,
    format: ['webp', 'avif'],
    screens: {
      xs: 320,
      sm: 640,
      md: 768,
      lg: 1024,
      xl: 1280,
      xxl: 1536
    },
    domains: ['cdn.example.com'],
    alias: {
      assets: '~/assets'
    }
  }
})
```

#### Route Rules cho Optimal Caching

```typescript
// nuxt.config.ts
export default defineNuxtConfig({
  routeRules: {
    // Homepage - prerender at build time
    '/': { prerender: true },
    
    // Blog - prerender all posts
    '/blog': { prerender: true },
    '/blog/**': { prerender: true },
    
    // Documentation - prerender
    '/docs/**': { prerender: true },
    
    // Product listing - ISR (revalidate every hour)
    '/products': { swr: 3600 },
    
    // Product detail - ISR
    '/products/**': { swr: 3600 },
    
    // User dashboard - no caching (always fresh)
    '/dashboard/**': { cache: false },
    
    // API routes - no caching
    '/api/**': { cache: false },
    
    // Admin - SPA mode
    '/admin/**': { ssr: false },
    
    // Auth pages - SSR for SEO
    '/auth/**': { ssr: true }
  }
})
```

#### Component Lazy Loading

```typescript
// nuxt.config.ts
export default defineNuxtConfig({
  components: {
    dirs: [
      {
        // Auto-lazy-load heavy components
        path: '~/components/heavy',
